//! Loaded-source clones keep a snapshot across original native activation.
use super::*;
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
fn check(reserve:bool){
 let mut doc=crate::html::parse_loaded_document("<html><body><span id=item data-note=old>original</span><div id=target></div></body></html>",&||Ok(())).unwrap();doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);run(&mut doc,&mut forms,&mut page,"var source=document.getElementById('item'),owner=document.implementation.createHTMLDocument('owner');owner.adoptNode(source);var sourceText=source.firstChild;");let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};assert!(matches!(page.state.inert_documents.node(source).unwrap().kind,Kind::Parsed{source:ParsedSource::Loaded(_),..}),"must exercise actual loaded payload");let limit=page.state.node_limit;if !reserve{page.state.node_limit=doc.nodes.len();}
 run(&mut doc,&mut forms,&mut page,"var clone=source.cloneNode(true),cloneText=clone.firstChild,list=clone.childNodes;if(clone===source||cloneText===sourceText||clone.ownerDocument!==owner||clone.parentNode!==null||clone.getAttribute('data-note')!=='old'||cloneText.data!=='original')throw 'genuine initial snapshot clone';");let Value::Host(clone)=page.runtime.execute("clone",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("clone")};assert_eq!(clone<FIRST_ENTRY,reserve,"actual native slot versus genuine inert identity");page.state.node_limit=limit;
 run(&mut doc,&mut forms,&mut page,"document.getElementById('target').appendChild(source);source.setAttribute('data-note','changed');sourceText.data='changed';if(source.ownerDocument!==document||source.getAttribute('data-note')!=='changed'||sourceText.data!=='changed')throw 'actual original activation and mutations';if(clone.getAttribute('data-note')!=='old'||cloneText.data!=='original')throw 'loaded clone alias: attribute='+clone.getAttribute('data-note')+', text='+cloneText.data;if(clone.ownerDocument!==owner||clone.childNodes!==list||list[0]!==cloneText||cloneText.ownerDocument!==owner||clone.parentNode!==null)throw 'snapshot identities and original owner retained';clone.setAttribute('data-note','independent');cloneText.data='independent';if(source.getAttribute('data-note')!=='changed'||sourceText.data!=='changed')throw 'clone changes never mutate active original';");
}
#[test]
fn loaded_clone_snapshot_native_reserved_identity_stays_independent(){check(true)}
#[test]
fn loaded_clone_snapshot_without_native_slot_stays_independent(){check(false)}

#[test]
fn loaded_clone_snapshot_no_slot_actual_payload_and_backing_refuse_without_publication_then_recover(){
 let mut doc=crate::html::parse_loaded_document("<html><body><span id=item data-note=old>original</span></body></html>",&||Ok(())).unwrap();let source_index=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("item")).unwrap();let text_index=doc.nodes[source_index].children[0];if let NodeKind::Element{tag,attrs,..}=&mut doc.nodes[source_index].kind{let mut wide=String::with_capacity(64);wide.push_str(tag);*tag=wide;let note=attrs.iter_mut().find(|a|a.name.html_is("data-note")).unwrap();let mut value=String::with_capacity(128);value.push_str("old");note.value=value.into();}if let NodeKind::Text(text)=&mut doc.nodes[text_index].kind{let mut wide=String::with_capacity(128);wide.push_str("original");*text=wide.into();}doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);run(&mut doc,&mut forms,&mut page,"var source=document.getElementById('item'),owner=document.implementation.createHTMLDocument('owner');owner.adoptNode(source);");let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};b.state.node_limit=b.doc.nodes.len();b.reserve_inert_entries(2,0,2).unwrap();let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits);let limit=b.state.retained_limit;let copies=b.state.copy_work;
 for storage in [true,false]{if storage{b.state.retained_limit=before.0+size_of::<u32>();}else{b.state.copy_work=0;}assert!(b.clone_inert_tree(source,true).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits),before);assert!(matches!(b.state.inert_documents.node(source).unwrap().kind,Kind::Parsed{source:ParsedSource::Loaded(_),..}));b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(clone)=b.clone_inert_tree(source,true).unwrap()else{panic!("clone")};assert!(clone>=FIRST_ENTRY);assert_eq!(b.doc.nodes.len(),before.4);assert_eq!(b.state.inert_documents.generated.len(),before.3+2);let links=b.state.inert_documents.entries[before.2..].iter().map(|entry|match entry{Entry::Node(node)=>node.children.capacity()*size_of::<u32>(),_=>panic!("genuine no-slot node")}).sum::<usize>();let mut snapshots=0;for source in &b.state.inert_documents.generated[before.3..]{snapshots+=node_bytes(&source.node)+size_of::<Node>()+2*size_of::<usize>();if let NodeKind::Element{tag,href,..}=&source.node.kind{assert!(tag.capacity()<64,"copy compacts original tag backing");snapshots+=tag.capacity()+href.as_ref().map_or(0,String::capacity);}}assert_eq!(b.state.retained,before.0+links+snapshots+b.state.inert_documents.backing_bytes()-before.1);
}
